function Metric({label,value,icon,detail,suffix,progress}){return <div className="card metric"><div className="metric-label">{label}<span><Icon name={icon} size={17}/></span></div><div className="metric-value">{value}<span>{suffix}</span></div><div className="metric-detail">{progress!==undefined&&<i className="metric-progress"><span style={{width:progress+'%'}}/></i>}{detail}</div></div>}
function MarkText({text,query}){if(!query.trim())return text;const at=text.toLocaleLowerCase().indexOf(query.trim().toLocaleLowerCase());if(at<0)return text;return <>{text.slice(0,at)}<mark>{text.slice(at,at+query.trim().length)}</mark>{text.slice(at+query.trim().length)}</>}

